8	//     sits inside the second octet): both range ends are admitted, the
9	//     addresses immediately before and after the range are not.
10	//   - 192.0.129.7/17 admits exactly 192.0.128.0 - 192.0.255.255 (the boundary
11	//     sits inside the third octet), with the same edge behavior.
12	//   - 192.0.2.3/31 is the two-address network 192.0.2.2 - 192.0.2.3: both
13	//     addresses take part in filtering — neither is set aside as a network or
14	//     broadcast address — while 192.0.2.1 and 192.0.2.4 stay out.
15	//
16	// Spelling the same network with a different in-range host address changes
17	// nothing, a boundary source arrives through source_ip or src_ip
18	// interchangeably, and a plain IPv4 address and its IPv4-mapped IPv6 spelling
19	// share one decision and one dotted output form, while a genuine IPv6 source
20	// with the same trailing 32 bits never matches. Dropped lines and blank lines
21	// never renumber later records, an out-of-range line with an invalid
22	// timestamp is still a counted failure with its reason and no event, and a
23	// batch in which every valid log misses the network ends cleanly with empty
24	// output and zero failures.
25	
26	import (
27		"strings"
28		"testing"
29	)
30	
31	// boundaryRangeCase pins one non-octet-aligned network: its canonical form
32	// plus the addresses that must and must not be admitted.
33	type boundaryRangeCase struct {
34		name      string
35		spelled   string // one host-spelled form of the network
36		canonical string
37		inside    []string
38		outside   []string
39	}
40	
41	// boundaryRanges lists the three networks under test with their exact edge
42	// addresses and the addresses immediately outside each edge.
43	var boundaryRanges = []boundaryRangeCase{
44		{
45			name:      "second-octet boundary /12",
46			spelled:   "172.16.5.9/12",
47			canonical: "172.16.0.0/12",
48			inside: []string{
49				"172.16.0.0",     // first address of the range
50				"172.16.5.9",     // the host the option was spelled with
51				"172.31.255.255", // last address of the range
52			},
53			outside: []string{
54				"172.15.255.255", // immediately below the range
55				"172.32.0.0",     // immediately above the range
56				"10.0.0.1",       // a different private network entirely
57			},
58		},
59		{
60			name:      "third-octet boundary /17",
61			spelled:   "192.0.129.7/17",
62			canonical: "192.0.128.0/17",
63			inside: []string{
64				"192.0.128.0",   // first address of the range
65				"192.0.129.7",   // the host the option was spelled with
66				"192.0.255.255", // last address of the range
67			},
68			outside: []string{
69				"192.0.127.255", // immediately below the range
70				"192.1.0.0",     // immediately above the range
71			},
72		},
73		{
74			name:      "two-address network /31",
75			spelled:   "192.0.2.3/31",
76			canonical: "192.0.2.2/31",
77			inside: []string{
78				"192.0.2.2", // not set aside as a network address
79				"192.0.2.3", // not set aside as a broadcast address
80			},
81			outside: []string{
82				"192.0.2.1", // immediately below the pair
83				"192.0.2.4", // immediately above the pair
84			},
85		},
86	}
87	
88	// TestSourceCIDRFilterNonOctetBoundaryMembership pins the exact admitted
89	// range of each boundary network against the normalized-address strings the
90	// filter actually compares.
91	func TestSourceCIDRFilterNonOctetBoundaryMembership(t *testing.T) {
92		for _, tc := range boundaryRanges {
93			t.Run(tc.name, func(t *testing.T) {
94				f, err := ParseSourceCIDRFilter(tc.spelled)
95				if err != nil {
96					t.Fatalf("ParseSourceCIDRFilter(%q) unexpected error: %v", tc.spelled, err)
97				}
98				if got := f.String(); got != tc.canonical {
99					t.Fatalf("ParseSourceCIDRFilter(%q).String() = %q, want %q", tc.spelled, got, tc.canonical)
100				}
101				for _, ip := range tc.inside {
102					if !f.admits(ip) {
103						t.Errorf("%s must admit range address %q", tc.canonical, ip)
104					}
105				}
106				for _, ip := range tc.outside {
107					if f.admits(ip) {
108						t.Errorf("%s must not admit %q", tc.canonical, ip)
109					}
110				}
111			})
112		}
113	}
114	
115	// TestSourceCIDRFilterBoundaryHostSpellingsAgree pins that writing the same
116	// network with a different in-range host address — including the range's own
117	// first and last addresses — parses to the same canonical network and admits
118	// exactly the same sources.
119	func TestSourceCIDRFilterBoundaryHostSpellingsAgree(t *testing.T) {
120		alternativeSpellings := map[string][]string{
121			"172.16.0.0/12":  {"172.16.5.9/12", "172.31.255.255/12", "172.16.0.0/12"},
122			"192.0.128.0/17": {"192.0.129.7/17", "192.0.255.255/17", "192.0.128.0/17"},
123			"192.0.2.2/31":   {"192.0.2.3/31", "192.0.2.2/31"},
124		}
125		probes := []string{
126			"172.15.255.255", "172.16.0.0", "172.31.255.255", "172.32.0.0",
127			"192.0.127.255", "192.0.128.0", "192.0.255.255", "192.1.0.0",
128			"192.0.2.1", "192.0.2.2", "192.0.2.3", "192.0.2.4",
129		}
130		for canonical, spellings := range alternativeSpellings {
131			reference, err := ParseSourceCIDRFilter(canonical)
132			if err != nil {
133				t.Fatal(err)
134			}
135			for _, spelled := range spellings {
136				f, err := ParseSourceCIDRFilter(spelled)
137				if err != nil {
138					t.Fatalf("ParseSourceCIDRFilter(%q) unexpected error: %v", spelled, err)
139				}
140				if got := f.String(); got != canonical {
141					t.Fatalf("host spelling %q must canonicalize to %q, got %q", spelled, canonical, got)
142				}
143				for _, probe := range probes {
144					if f.admits(probe) != reference.admits(probe) {
145						t.Fatalf("host spelling %q disagrees with %q on %q", spelled, canonical, probe)
146					}
147				}
148			}
149		}
150	}
151	
152	// TestSourceCIDRFilterBoundaryStreamBehavior drives a mixed stream through
153	// the /12 filter: range-edge hits through source_ip and src_ip, a mapped
154	// spelling of the first range address, the just-outside addresses, a genuine
155	// IPv6 source whose tail equals an in-range address, an absent source, a
156	// blank line, and an out-of-range line whose timestamp is invalid. The
157	// admitted events keep input order, physical line numbers, their normalized
158	// dotted source and their extra fields with no filter marker; the invalid
159	// line is a counted failure with its reason and no event; everything else
160	// leaves no trace.
161	func TestSourceCIDRFilterBoundaryStreamBehavior(t *testing.T) {
162		filter, err := ParseSourceCIDRFilter("172.16.5.9/12")
163		if err != nil {
164			t.Fatal(err)
165		}
166		input := strings.Join([]string{
167			`{"timestamp":` + validTS + `,"action":"range-first","source_ip":"172.16.0.0"}`,               // line 1 admitted
168			`{"timestamp":` + validTS + `,"action":"range-last","src_ip":"172.31.255.255","trace":"t-9"}`, // line 2 admitted via alias
169			`{"timestamp":` + validTS + `,"action":"mapped-first","source_ip":"::ffff:172.16.0.0"}`,       // line 3 admitted, prints dotted
170			`{"timestamp":` + validTS + `,"action":"just-below","source_ip":"172.15.255.255"}`,            // line 4 dropped
171			`{"timestamp":` + validTS + `,"action":"just-above","source_ip":"172.32.0.0"}`,                // line 5 dropped
172			`{"timestamp":` + validTS + `,"action":"v6-same-tail","source_ip":"::172.16.0.0"}`,            // line 6 dropped (genuine IPv6)
173			`{"timestamp":` + validTS + `,"action":"no-source"}`,                                          // line 7 dropped (absent)
174			``, // line 8 blank
175			`{"timestamp":"not-a-time","action":"broken-outside","source_ip":"172.32.0.0"}`,             // line 9 failure
176			`{"timestamp":` + validTS + `,"action":"tail-hit","source_ip":"172.16.5.9","keep":{"n":2}}`, // line 10 admitted
177		}, "\n") + "\n"
178	
179		results, failures := runNormalizeFiltered(t, input, &filter)
180	
181		if failures != 1 {
182			t.Fatalf("the invalid line must count as one failure even though its source is out of range, got %d", failures)
183		}
184		if len(results) != 5 {
185			t.Fatalf("expected 4 admitted successes + 1 failure = 5 records, got %d: %#v", len(results), results)
186		}
187	
188		want := []struct {
189			line     float64
190			ok       bool
191			action   string
192			sourceIP string
193		}{
194			{1, true, "range-first", "172.16.0.0"},
195			{2, true, "range-last", "172.31.255.255"},
196			{3, true, "mapped-first", "172.16.0.0"}, // mapped spelling prints the same dotted address
197			{9, false, "broken-outside", ""},
198			{10, true, "tail-hit", "172.16.5.9"},
199		}
200		for i, w := range want {
201			got := results[i]
202			if got["line"] != w.line || got["ok"] != w.ok {
203				t.Fatalf("record %d mismatch: want line=%v ok=%v, got %#v", i, w.line, w.ok, got)
204			}
205			if _, marked := got["filtered"]; marked {
206				t.Fatalf("record %d must carry no filter marker: %#v", i, got)
207			}
208			if !w.ok {
209				if _, exists := got["event"]; exists {
210					t.Fatalf("the out-of-range invalid line must carry no event: %#v", got)
211				}
212				if msg, _ := got["error"].(string); !strings.Contains(msg, FieldTimestamp) {
213					t.Fatalf("the failure must keep its original timestamp reason, got %q", msg)
214				}
215				continue
216			}
217			event := eventOf(t, got)
218			if event["action"] != w.action || event["source_ip"] != w.sourceIP {
219				t.Fatalf("record %d event mismatch: %#v", i, event)
220			}
221		}
222	
223		// Field normalization and extra preservation are exactly the unfiltered
224		// behavior: the alias-sourced line keeps its extra string, the trailing
225		// hit keeps its nested object.
226		if got := eventOf(t, results[1])["extra"].(map[string]any)["trace"]; got != "t-9" {
227			t.Fatalf("extra fields of an admitted alias line must survive filtering, got %#v", got)
228		}
229		if got := eventOf(t, results[4])["extra"].(map[string]any)["keep"].(map[string]any)["n"]; got != float64(2) {
230			t.Fatalf("nested extra content of an admitted line must survive filtering, got %#v", got)
231		}
232	}
233	
234	// TestSourceCIDRFilterSlash31KeepsBothAddresses pins the two-address network:
235	// 192.0.2.3/31 admits both 192.0.2.2 and 192.0.2.3 — neither address is
236	// excluded as a network or broadcast address — while the immediate neighbors
237	// 192.0.2.1 and 192.0.2.4 are dropped. The same network spelled with its
238	// other host address selects identically.
239	func TestSourceCIDRFilterSlash31KeepsBothAddresses(t *testing.T) {
240		input := strings.Join([]string{
241			`{"timestamp":` + validTS + `,"action":"below","source_ip":"192.0.2.1"}`,             // line 1 dropped
242			`{"timestamp":` + validTS + `,"action":"low-of-pair","source_ip":"192.0.2.2"}`,       // line 2 admitted
243			`{"timestamp":` + validTS + `,"action":"high-of-pair","src_ip":"192.0.2.3"}`,         // line 3 admitted via alias
244			`{"timestamp":` + validTS + `,"action":"mapped-low","source_ip":"::ffff:192.0.2.2"}`, // line 4 admitted
245			`{"timestamp":` + validTS + `,"action":"above","source_ip":"192.0.2.4"}`,             // line 5 dropped
246		}, "\n") + "\n"
247	
248		var outputs []string
249		for _, spelled := range []string{"192.0.2.3/31", "192.0.2.2/31"} {
250			filter, err := ParseSourceCIDRFilter(spelled)
251			if err != nil {
252				t.Fatal(err)
253			}
254			results, failures := runNormalizeFiltered(t, input, &filter)
255			if failures != 0 {
256				t.Fatalf("filter %q: an all-valid batch must have zero failures, got %d", spelled, failures)
257			}
258			if len(results) != 3 {
259				t.Fatalf("filter %q: both /31 addresses and the mapped spelling must survive, got %#v", spelled, results)
260			}
261			wantLines := []float64{2, 3, 4}
262			wantActions := []string{"low-of-pair", "high-of-pair", "mapped-low"}
263			wantSources := []string{"192.0.2.2", "192.0.2.3", "192.0.2.2"}
264			for i := range wantLines {
265				if results[i]["line"] != wantLines[i] || results[i]["ok"] != true {
266					t.Fatalf("filter %q: record %d must keep physical line %v: %#v", spelled, i, wantLines[i], results[i])
267				}
268				event := eventOf(t, results[i])
269				if event["action"] != wantActions[i] || event["source_ip"] != wantSources[i] {
270					t.Fatalf("filter %q: record %d event mismatch: %#v", spelled, i, event)
271				}
272			}
273			var rendered strings.Builder
274			for _, r := range results {
275				rendered.WriteString(eventOf(t, r)["action"].(string))
276				rendered.WriteByte(';')
277			}
278			outputs = append(outputs, rendered.String())
279		}
280		if outputs[0] != outputs[1] {
281			t.Fatalf("the two host spellings of one /31 must select identically: %q vs %q", outputs[0], outputs[1])
282		}
283	}
284	
285	// TestSourceCIDRFilterBoundaryAllMissesCleanEmpty pins that a batch of valid
286	// logs whose sources all fall immediately outside a boundary network — or are
287	// absent — ends normally: no records, zero failures.
288	func TestSourceCIDRFilterBoundaryAllMissesCleanEmpty(t *testing.T) {
289		filter, err := ParseSourceCIDRFilter("192.0.129.7/17")
290		if err != nil {
291			t.Fatal(err)
292		}
293		input := strings.Join([]string{
294			`{"timestamp":` + validTS + `,"action":"just-below","source_ip":"192.0.127.255"}`,
295			`{"timestamp":` + validTS + `,"action":"just-above","source_ip":"192.1.0.0"}`,
296			`{"timestamp":` + validTS + `,"action":"v6-same-tail","source_ip":"::192.0.128.0"}`,
297			`{"timestamp":` + validTS + `,"action":"no-source"}`,
298		}, "\n") + "\n"
299	
300		results, failures := runNormalizeFiltered(t, input, &filter)
301		if failures != 0 {
302			t.Fatalf("an all-valid batch must have zero failures even when nothing is admitted, got %d", failures)
303		}
304		if len(results) != 0 {
305			t.Fatalf("every valid log missed the network, so no record may be emitted, got %#v", results)
306		}
307	}
