55	// assertSourceConflictFailure requires the single emitted record to be an
56	// ok:false source_ip conflict with no event, naming both normalized addresses
57	// in the error (a two-legal-address conflict, not an invalid-address or
58	// type error).
59	func assertSourceConflictFailure(t *testing.T, r map[string]any) {
60		t.Helper()
61		if r["ok"] != false {
62			t.Fatalf("two legal distinct sources must fail whole line: %#v", r)
63		}
64		if _, exists := r["event"]; exists {
65			t.Fatalf("conflicting sources must not emit an event: %#v", r)
66		}
