68		if !strings.Contains(msg, FieldSourceIP) || !strings.Contains(msg, "conflicting values") {
69			t.Fatalf("error must report a source_ip value conflict, got %q", msg)
70		}
71		if strings.Contains(msg, "invalid IP address") || strings.Contains(msg, "got null") {
72			t.Fatalf("two legal addresses must not be reported as invalid/null: %q", msg)
73		}
74	}
