115	// runDualSource runs one dual-source log through both the filtered and
116	// unfiltered reader and returns (filtered results, filtered failures,
117	// unfiltered results). It pins filtered==unfiltered for the failure path:
118	// enabling the filter must not change the failure reason.
119	func runDualSource(t *testing.T, input string) ([]map[string]any, int, []map[string]any) {
120		t.Helper()
121		filter, err := ParseSourceCIDRFilter(dualSourceCIDR)
122		if err != nil {
123			t.Fatal(err)
124		}
125		fResults, fFail := runNormalizeFiltered(t, input, &filter)
126		uResults := runNormalize(t, input)
127		return fResults, fFail, uResults
