130	// TestDualSourceMappedEquivalentMergeAndAdmit pins the headline merge:
131	// 192.0.2.7 and ::ffff:192.0.2.7 are the same legal address in two spellings,
132	// so they merge into one successful event that the filter admits, printing
133	// the dotted form. The same merge using only the mapped spelling is dropped
134	// cleanly when both equivalents normalize outside the network.
135	func TestDualSourceMappedEquivalentMergeAndAdmit(t *testing.T) {
136		// In-network equivalent pair: merge then admit, in every member ordering.
137		for _, in := range dualSourceOrderings(`"192.0.2.7"`, `"::ffff:192.0.2.7"`) {
138			fResults, fFail, uResults := runDualSource(t, in)
139			if fFail != 0 || len(fResults) != 1 || fResults[0]["ok"] != true {
140				t.Fatalf("equivalent in-network pair must merge into one admitted success: %s -> %#v failures=%d",
141					in, fResults, fFail)
142			}
143			event := eventOf(t, fResults[0])
144			if event["source_ip"] != "192.0.2.7" {
145				t.Fatalf("merged source_ip = %v, want 192.0.2.7 (%s)", event["source_ip"], in)
146			}
147			if event["timestamp"] != "2026-01-02T00:00:00Z" || event["action"] != "ok" {
148				t.Fatalf("other mapped fields must stay legal: %#v (%s)", event, in)
149			}
150			if _, exists := event["extra"]; exists {
151				t.Fatalf("no unknown fields were given, extra must be absent: %#v (%s)", event, in)
152			}
153			// Unfiltered the same line is a success; enabling the filter must
154			// not alter that record.
155			if len(uResults) != 1 || uResults[0]["ok"] != true {
156				t.Fatalf("unfiltered equivalent pair must also succeed: %#v", uResults)
157			}
158			if !jsonEqualResult(fResults[0], uResults[0]) {
159				t.Fatalf("filter must not change the merged success:\nfiltered:   %#v\nunfiltered: %#v", fResults[0], uResults[0])
160			}
161		}
162	
163		// Two equivalents both outside the network: they still merge into a
164		// valid success, but the filter drops it — no record and no failure.
165		outside := dualSourceLog(`"198.51.100.7"`, `"::ffff:198.51.100.7"`)
166		fResults, fFail, uResults := runDualSource(t, outside)
167		if fFail != 0 {
168			t.Fatalf("equivalent out-of-network pair must not be a failure, got %d", fFail)
169		}
170		if len(fResults) != 0 {
171			t.Fatalf("both equivalents out of network must produce no record, got %#v", fResults)
172		}
173		// ... but the merge is genuinely valid: unfiltered it is one ok event
174		// with the dotted form, proving this is a filter drop rather than a
175		// conflict.
176		if len(uResults) != 1 || uResults[0]["ok"] != true {
177			t.Fatalf("out-of-network equivalents must merge validly without a filter: %#v", uResults)
178		}
179		if got := eventOf(t, uResults[0])["source_ip"]; got != "198.51.100.7" {
180			t.Fatalf("out-of-network equivalents must merge to 198.51.100.7, got %v", got)
181		}
182	}
