410	// TestDualSourceBatchPreservesPhysicalLineNumbers drives all the source
411	// problems through one batch that also contains an in-network success, an
412	// out-of-network legal event, and a blank line. Filtered: the in-network
413	// success and later successes still emit; failures keep their ORIGINAL
414	// physical line numbers; dropped/blank lines never renumber; later successes
415	// emit normally. Unfiltered: every failure reason is identical.
416	func TestDualSourceBatchPreservesPhysicalLineNumbers(t *testing.T) {
417		filter, err := ParseSourceCIDRFilter(dualSourceCIDR)
418		if err != nil {
419			t.Fatal(err)
420		}
421		input := strings.Join([]string{
422			// line 1: in-network single-source success (control).
423			`{"timestamp":` + validTSLiteral + `,"action":"hit-before","source_ip":"192.0.2.5"}`,
424			// line 2: two legal distinct, one in one out -> conflict failure.
425			dualSourceLog(`"192.0.2.7"`, `"198.51.100.7"`),
426			// line 3: equivalent pair both outside -> merged success, dropped.
427			dualSourceLog(`"198.51.100.1"`, `"::ffff:198.51.100.1"`),
428			// line 4: blank -> skipped, still counts.
429			"",
430			// line 5: ::192.0.2.7 vs 192.0.2.7 -> conflict failure.
431			dualSourceLog(`"::192.0.2.7"`, `"192.0.2.7"`),
432			// line 6: one invalid address -> invalid-address failure.
433			dualSourceLog(`"192.0.2.7"`, `"not-an-ip"`),
434			// line 7: one explicit null -> type failure.
435			dualSourceLog(`null`, `"192.0.2.7"`),
436			// line 8: two distinct legal both outside -> conflict failure.
437			dualSourceLog(`"198.51.100.2"`, `"198.51.100.3"`),
438			// line 9: later in-network success -> must emit normally.
439			`{"timestamp":` + validTSLiteral + `,"action":"hit-after","source_ip":"192.0.2.9"}`,
440			// line 10: later out-of-network single-source legal -> dropped.
441			`{"timestamp":` + validTSLiteral + `,"action":"outside","source_ip":"10.0.0.1"}`,
442		}, "\n") + "\n"
443	
444		var fOut, uOut bytes.Buffer
445		fFailures, err := NormalizeReaderFiltered(strings.NewReader(input), &fOut, &filter)
446		if err != nil {
447			t.Fatalf("filtered run error: %v", err)
448		}
449		uFailures, err := NormalizeReader(strings.NewReader(input), &uOut)
450		if err != nil {
451			t.Fatalf("unfiltered run error: %v", err)
452		}
453	
454		// Five bad lines (2,5,6,7,8) regardless of the filter.
455		if fFailures != 5 || uFailures != 5 {
456			t.Fatalf("five bad lines must be counted with and without filter, got %d and %d", fFailures, uFailures)
457		}
458	
459		decode := func(b *bytes.Buffer) []map[string]any {
460			var rs []map[string]any
461			dec := json.NewDecoder(b)
462			for {
463				var m map[string]any
464				if err := dec.Decode(&m); err != nil {
465					if err == io.EOF {
466						return rs
467					}
468					t.Fatalf("decode: %v", err)
469				}
470				rs = append(rs, m)
471			}
472		}
473		fResults := decode(&fOut)
474		uResults := decode(&uOut)
475	
476		// Filtered: lines 1 (hit), 2,5,6,7,8 (failures), 9 (hit) = 7 records.
477		if len(fResults) != 7 {
478			t.Fatalf("expected 2 admitted successes + 5 failures = 7 records, got %d: %#v", len(fResults), fResults)
479		}
480		wantFilteredLines := []float64{1, 2, 5, 6, 7, 8, 9}
481		for i, ln := range wantFilteredLines {
482			if fResults[i]["line"] != ln {
483				t.Fatalf("filtered record %d must carry physical line %v, got %v: %#v",
484					i, ln, fResults[i]["line"], fResults[i])
485			}
486		}
487		if fResults[0]["ok"] != true || eventOf(t, fResults[0])["action"] != "hit-before" {
488			t.Fatalf("record 0 must be the line-1 in-network hit: %#v", fResults[0])
489		}
490		if fResults[6]["ok"] != true || eventOf(t, fResults[6])["action"] != "hit-after" {
491			t.Fatalf("record 6 must be the line-9 in-network hit, emitted normally after the failures: %#v", fResults[6])
492		}
493		// Failure records 1..5 carry no event and keep their source_ip reasons.
494		for i := 1; i <= 5; i++ {
495			if fResults[i]["ok"] != false {
496				t.Fatalf("record %d (line %v) must be a failure: %#v", i, wantFilteredLines[i], fResults[i])
497			}
498			if _, exists := fResults[i]["event"]; exists {
499				t.Fatalf("failure record %d must carry no event: %#v", i, fResults[i])
500			}
501			msg, _ := fResults[i]["error"].(string)
502			if !strings.Contains(msg, FieldSourceIP) {
503				t.Fatalf("failure record %d must name source_ip, got %q", i, msg)
504			}
505		}
506		assertSourceConflictFailure(t, fResults[1]) // line 2
507		assertSourceConflictFailure(t, fResults[2]) // line 5
508		assertSourceInvalidAddress(t, fResults[3])  // line 6
509		assertSourceNullType(t, fResults[4])        // line 7
510		assertSourceConflictFailure(t, fResults[5]) // line 8
511	
512		// Without filter: lines 1,2,3,5,6,7,8,9,10 emit (line 3 and 10 survive
513		// as successes), blank line 4 only counts. = 9 records.
514		if len(uResults) != 9 {
515			t.Fatalf("unfiltered expected 9 records (no blank line 4), got %d: %#v", len(uResults), uResults)
516		}
517		wantUnfilteredLines := []float64{1, 2, 3, 5, 6, 7, 8, 9, 10}
518		for i, ln := range wantUnfilteredLines {
519			if uResults[i]["line"] != ln {
520				t.Fatalf("unfiltered record %d must carry physical line %v, got %v", i, ln, uResults[i]["line"])
521			}
522		}
523		// Every filtered failure record equals its unfiltered counterpart (same
524		// physical line, same reason, no event).
525		for _, ln := range []float64{2, 5, 6, 7, 8} {
526			var fR, uR map[string]any
527			for _, r := range fResults {
528				if r["line"] == ln {
529					fR = r
530				}
531			}
532			for _, r := range uResults {
533				if r["line"] == ln {
534					uR = r
535				}
536			}
537			if !jsonEqualResult(fR, uR) {
538				t.Fatalf("line %v failure must be identical with/without filter:\nfiltered:   %#v\nunfiltered: %#v",
539					ln, fR, uR)
540			}
541		}
542	}
543	
544	// TestDualSourceAllMissCleanEmpty pins that a batch consisting entirely of
545	// legal logs whose (merged) sources all miss the network — equivalent pairs
546	// both outside, genuine IPv6 pairs, absent sources — ends normally: stdout
547	// empty, zero failures. Conflicts and invalid values are deliberately absent
548	// so this exercises the all-miss case rather than the failure case.
549	func TestDualSourceAllMissCleanEmpty(t *testing.T) {
550		filter, err := ParseSourceCIDRFilter(dualSourceCIDR)
551		if err != nil {
552			t.Fatal(err)
553		}
554		input := strings.Join([]string{
555			dualSourceLog(`"198.51.100.7"`, `"::ffff:198.51.100.7"`),                       // equivalent, both out
556			dualSourceLog(`"::192.0.2.7"`, `"::192.0.2.7"`),                                // genuine IPv6 pair, both out
557			`{"timestamp":` + validTSLiteral + `,"action":"no-source"}`,                    // absent source
558			`{"timestamp":` + validTSLiteral + `,"action":"v6","source_ip":"2001:db8::1"}`, // IPv6
559		}, "\n") + "\n"
560	
561		var out bytes.Buffer
562		failures, err := NormalizeReaderFiltered(strings.NewReader(input), &out, &filter)
563		if err != nil {
564			t.Fatalf("all-miss run error: %v", err)
565		}
566		if failures != 0 {
567			t.Fatalf("all logs legal -> zero failures even though nothing is admitted, got %d", failures)
568		}
569		if out.Len() != 0 {
570			t.Fatalf("every valid log missed the network, so stdout must be empty, got %q", out.String())
571		}
572	}
